function escapeHtml(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function debounce(fn,delay=350){let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>fn(...args),delay)}}
async function api(url){const response=await fetch(url);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"The data service could not complete this request.");return data}
function showResults(container,rows,renderer,onPick){container.innerHTML=rows.length?rows.map((row,i)=>`<button type="button" class="result" data-i="${i}">${renderer(row)}</button>`).join(""):`<div class="result"><strong>No matches found</strong><span>Try a broader search.</span></div>`;container.hidden=false;container.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{onPick(rows[Number(button.dataset.i)]);container.hidden=true}))}

const METRIC_HELP={"Financial outcome":"Estimated five-year earnings after path costs.","Time to earnings":"How quickly you begin earning meaningful income.","Debt & upfront cost":"How much you may pay yourself or borrow.","Employment demand":"How strongly employers are expected to need workers.","AI resilience":"How difficult the career’s main tasks may be to automate.","Career flexibility":"How easily these skills may transfer to other careers."};
