function schoolTuition(){if(!selectedSchool)return;const residency=$("residency").value,annual=Number(get(selectedSchool,`latest.cost.tuition.${residency}`)||0),months=Number($("degree").value||48),years=months/12,net=Number(get(selectedSchool,"latest.cost.avg_net_price.overall")||0);$("duration").value=months;if(annual){$("cost").value=Math.round(annual*years);$("costHint").textContent=`Estimated ${years}-year tuition using ${residency==="in_state"?"in-state":"out-of-state"} published tuition. Fees and living costs may be extra.`}else if(net){$("cost").value=Math.round(net*years);$("costHint").textContent=`Estimated ${years}-year cost using the school’s average annual net price. Verify your aid offer.`}}
function updateDebtGuidance(){const debt=Number($("debt").value||0);if(!debt)return $("debtGuidance").textContent="Enter the amount you expect to borrow. We’ll estimate a monthly payment.";const rate=.065/12,payments=120,monthly=debt*rate/(1-Math.pow(1+rate,-payments));$("debtGuidance").textContent=`Rough 10-year payment: ${money(monthly)}/month at 6.5% interest. Compare this with expected take-home pay.`}
async function loadSchoolPrograms(school){const select=$("collegePlan");selectedProgram=null;schoolProgramChoices=[];select.disabled=true;select.innerHTML='<option value="">Loading this school’s degree plans…</option>';$("collegePlanHint").textContent="Loading official College Scorecard field-of-study records.";try{const data=await api(`/api/schools?programs=${encodeURIComponent(get(school,"id"))}`),programs=data.programs||[];schoolProgramChoices=programs;select.innerHTML='<option value="">Choose a degree plan</option>'+programs.map((program,index)=>`<option value="${escapeHtml(program.code)}" data-program-index="${index}">${escapeHtml(program.title)} · ${escapeHtml(program.credential)}</option>`).join("");select.disabled=!programs.length;$("collegePlanHint").textContent=programs.length?`${programs.length} degree plan${programs.length===1?"":"s"} found for this school. Programs may group similar majors together.`:"No field-of-study records were returned for this school. Try another school or verify its programs on the admissions website."}catch(error){select.innerHTML='<option value="">Degree plans unavailable</option>';$("collegePlanHint").textContent=error.message}}
const searchSchools=debounce(async()=>{const query=$("schoolSearch").value.trim();if(query.length<2)return;try{const{results}=await api(`/api/schools?search=${encodeURIComponent(query)}`);showResults($("schoolResults"),results,school=>`<strong>${escapeHtml(get(school,"school.name"))}</strong><span>${escapeHtml([get(school,"school.city"),get(school,"school.state")].filter(Boolean).join(", "))}</span>`,school=>{selectedSchool=school;$("schoolSearch").value=get(school,"school.name")||"";$("schoolSelected").innerHTML=`Using official College Scorecard data for <strong>${escapeHtml(get(school,"school.name"))}</strong>`;$("schoolSelected").hidden=false;loadSchoolPrograms(school);const debt=get(school,"latest.aid.median_debt.completers.overall");schoolTuition();if(debt)$("debt").value=Math.round(debt);updateDebtGuidance()})}catch(e){$("schoolResults").innerHTML=`<div class="result"><strong>Search unavailable</strong><span>${escapeHtml(e.message)}</span></div>`;$("schoolResults").hidden=false}});
const searchCareers=debounce(async()=>{const query=$("careerSearch").value.trim();if(query.length<2)return;try{const{results}=await api(`/api/careers?search=${encodeURIComponent(query)}`);showResults($("careerResults"),results,career=>`<strong>${escapeHtml(career.name)}</strong><span>O*NET-SOC ${escapeHtml(career.code)}${career.brightOutlook?" · Bright Outlook":""}</span>`,async career=>{$("careerSearch").value=career.name;$("careerSelected").textContent="Loading career details…";$("careerSelected").hidden=false;try{selectedCareer=await api(`/api/careers?code=${encodeURIComponent(career.code)}`);$("careerSelected").textContent=`O*NET-SOC ${selectedCareer.code} · ${selectedCareer.outlook?.category||"Outlook unavailable"}`;const median=Number(selectedCareer.wage?.annual_median||selectedCareer.wage?.annual_median_over||0);if(median&&!$("startingPay").value)$("startingPay").placeholder=`About ${money(median*.82)}`}catch(e){selectedCareer=null;$("careerSelected").textContent=e.message}})}catch(e){$("careerResults").innerHTML=`<div class="result"><strong>Search unavailable</strong><span>${escapeHtml(e.message)}</span></div>`;$("careerResults").hidden=false}});

async function chooseMappedCareer(career){$("careerSearch").value=career.name;$("careerSelected").textContent="Loading civilian career details…";$("careerSelected").hidden=false;try{selectedCareer=await api(`/api/careers?code=${encodeURIComponent(career.code)}`);$("careerSelected").textContent=`Selected civilian match · ${selectedCareer.name} · ${selectedCareer.code}`;const median=Number(selectedCareer.wage?.annual_median||selectedCareer.wage?.annual_median_over||0);if(median&&!$("startingPay").value)$("startingPay").placeholder=`About ${money(median*.82)}`}catch(e){selectedCareer=null;$("careerSelected").textContent=e.message}}
function renderMilitaryChoice(job){selectedMilitary=job;$("provider").value=job.title;$("militaryJobSearch").value=`${job.code} · ${job.title.replace(/\s*\([^)]*\)\s*$/,"")}`;const choices=job.occupations||[];$("militaryJobSelected").innerHTML=`<strong>${escapeHtml(job.title)}</strong><div class="mapped-careers">${choices.map((career,i)=>`<button type="button" data-career="${i}"><b>${escapeHtml(career.name)}</b><span>${escapeHtml(career.code)}</span></button>`).join("")||"<span>No civilian career matches were returned.</span>"}</div><small>Choose the civilian career this specialty should be evaluated against.</small>`;$("militaryJobSelected").hidden=false;$("militaryJobSelected").querySelectorAll("[data-career]").forEach(button=>button.addEventListener("click",()=>chooseMappedCareer(choices[Number(button.dataset.career)])))}
const searchMilitaryJobs=debounce(async()=>{const query=$("militaryJobSearch").value.trim();if(query.length<2)return;try{const params=new URLSearchParams({military:query,branch:$("militaryBranch").value,track:$("militaryTrack").value});const{results}=await api(`/api/careers?${params}`);showResults($("militaryJobResults"),results,job=>`<strong>${escapeHtml(job.code)} · ${escapeHtml(job.title.replace(/\s*\([^)]*\)\s*$/,"") )}</strong><span>${job.occupations.length} civilian career match${job.occupations.length===1?"":"es"}</span>`,renderMilitaryChoice)}catch(e){$("militaryJobResults").innerHTML=`<div class="result"><strong>Military job search unavailable</strong><span>${escapeHtml(e.message)}</span></div>`;$("militaryJobResults").hidden=false}});

function configurePayGrades(){const track=$("militaryTrack").value,grades=PAY_GRADES[track];$("payGrade").innerHTML=Object.keys(grades).map(grade=>`<option>${grade}</option>`).join("");$("monthlyBasicPay").value=Object.values(grades)[0];$("monthlyFood").value=track==="commissioned"?328.48:476.95;updateMilitarySummary()}
function militaryInputs(){const monthlyBasic=Number($("monthlyBasicPay").value||0),housing=Number($("monthlyHousing").value||0),food=Number($("monthlyFood").value||0),special=Number($("monthlySpecialPay").value||0),bonus=Number($("militaryBonus").value||0),commitment=Number($("serviceCommitment").value||0),education=Number($("educationBenefit").value||0),realization=Number($("benefitRealization").value||0);const annualCash=(monthlyBasic+housing+food+special)*12,educationExpected=education*realization;return{grade:$("payGrade").value,monthlyBasic,housing,food,special,bonus,commitment,education,realization,educationExpected,annualCash}}
function updateMilitarySummary(){if(activePath!=="military")return;const m=militaryInputs();$("militaryCompSummary").innerHTML=`Estimated first-year cash compensation: <strong>${money(m.annualCash+m.bonus)}</strong> · Expected education value: <strong>${money(m.educationExpected)}</strong><br>Housing and food allowances are generally tax-advantaged; confirm eligibility and location-specific amounts.`}
function tradeInputs(){const start=Number($("tradeStartWage").value||0),journey=Number($("tradeJourneyWage").value||0),months=Number($("tradeProgramMonths").value||0),steps=Math.max(1,Number($("tradeRaises").value||1)),hoursWeek=Number($("tradeHoursWeek").value||0),weeksYear=Number($("tradeWeeksYear").value||0),tools=Number($("tradeToolsCost").value||0),classes=Number($("tradeClassCost").value||0),license=Number($("tradeLicenseCost").value||0),support=Number($("tradeSupport").value||0),monthlyHours=hoursWeek*weeksYear/12;let fiveYearEarnings=0,firstYearEarnings=0;for(let month=0;month<60;month++){let wage=journey;if(month<months){const step=Math.min(steps-1,Math.floor(month/Math.max(1,months/steps)));wage=start+(journey-start)*(step/steps)}const earned=wage*monthlyHours;fiveYearEarnings+=earned;if(month<12)firstYearEarnings+=earned}const grossCost=tools+classes+license,netCost=Math.max(0,grossCost-support);return{start,journey,months,steps,hoursWeek,weeksYear,tools,classes,license,support,grossCost,netCost,fiveYearEarnings,firstYearEarnings}}
function updateTradeSummary(){if(activePath!=="trade")return;const t=tradeInputs();$("tradeSummary").innerHTML=`Estimated first-year apprentice earnings: <strong>${money(t.firstYearEarnings)}</strong> · Five-year gross earnings: <strong>${money(t.fiveYearEarnings)}</strong><br>Estimated net tools, instruction, and licensing cost: <strong>${money(t.netCost)}</strong>.`}
function trainingInputs(){const type=$("credentialType").value,months=Number($("trainingMonths").value||0),tuition=Number($("trainingTuition").value||0),exam=Number($("trainingExamCost").value||0),materials=Number($("trainingMaterials").value||0),renewal=Number($("trainingRenewal").value||0),support=Number($("trainingSupport").value||0),earnWhile=Number($("trainingEarnWhile").value||0),completion=Number($("completionProbability").value||0),placement=Number($("placementRate").value||0)/100,salary=Number($("trainingStartingSalary").value||0),fallback=Number($("fallbackSalary").value||0),success=completion*placement,grossCost=tuition+exam+materials,netCost=Math.max(0,grossCost-support),trainingYears=months/12,workingYears=Math.max(0,5-trainingYears),renewalExpected=renewal*workingYears*completion,fiveYearEarnings=earnWhile*trainingYears+workingYears*(success*salary+(1-success)*fallback),fiveYearNet=fiveYearEarnings-netCost-renewalExpected;return{type,months,tuition,exam,materials,renewal,support,earnWhile,completion,placement,salary,fallback,success,grossCost,netCost,trainingYears,workingYears,renewalExpected,fiveYearEarnings,fiveYearNet}}
function updateTrainingSummary(){if(activePath!=="training")return;const t=trainingInputs();$("trainingSummary").innerHTML=`Combined completion-and-placement probability: <strong>${Math.round(t.success*100)}%</strong> · Probability-adjusted five-year earnings: <strong>${money(t.fiveYearEarnings)}</strong><br>Net initial cost: <strong>${money(t.netCost)}</strong> · Expected renewal cost: <strong>${money(t.renewalExpected)}</strong>.`}
function setPath(path,initial=false){activePath=path;const p=PATHS[path],college=path==="college",military=path==="military",trade=path==="trade",training=path==="training",custom=trade||training;document.querySelectorAll(".path-choice").forEach(button=>{const on=button.dataset.path===path;button.classList.toggle("active",on);button.setAttribute("aria-checked",on)});$("schoolField").hidden=!college;$("degreeField").hidden=!college;$("residencyField").hidden=!college;$("providerField").hidden=college||military;$("providerSuggestions").innerHTML=(PROVIDERS[path]||[]).map(value=>`<option value="${escapeHtml(value)}"></option>`).join("");$("militaryBranchField").hidden=!military;$("militaryTrackField").hidden=!military;$("militaryJobField").hidden=!military;$("militaryCompensation").hidden=!military;$("tradeEconomics").hidden=!trade;$("trainingEconomics").hidden=!training;["costField","aidField","durationField","earnWhileField","startingPayField"].forEach(id=>$(id).hidden=custom);$("careerLabel").textContent=military?"Civilian career equivalent":p.career;$("careerSearch").placeholder=military?"Choose a mapped career above, or search another":"Type a career to choose";$("providerLabel").textContent=p.provider;$("providerHint").textContent=p.hint||"";$("costLabel").childNodes[0].nodeValue=p.costLabel+" ";$("aidLabel").childNodes[0].nodeValue=p.aid+" ";$("aidHint").textContent=p.aidHint;$("durationHint").textContent=military?"Months until regular military pay begins.":"Time before entering the target career full time.";if(!initial){$("duration").value=p.duration;$("cost").value=p.cost;$("grants").value="0";$("debt").value=p.debt;$("earnWhile").value=p.earn;$("provider").value="";$("careerSearch").value="";$("careerSelected").hidden=true;selectedCareer=null;selectedMilitary=null;$("militaryJobSearch").value="";$("militaryJobSelected").hidden=true;$("formMessage").textContent=""}if(college)schoolTuition();else $("costHint").textContent=p.costHint;if(military&&(!$("payGrade").options.length||!initial))configurePayGrades();if(trade)updateTradeSummary();if(training)updateTrainingSummary();updateDebtGuidance()}

function aiResilience(career,path){const text=[career.description,...(career.tasks||[])].join(" ").toLowerCase();let score=55;if(/repair|install|operate|inspect|patient|physical|equipment|construction|emergency|maintain|diagnos|treat|hands-on/.test(text))score+=20;if(/negotiate|counsel|supervis|coordinate|care for|public safety/.test(text))score+=10;if(/enter data|compile|routine|prepare reports|process information|clerical/.test(text))score-=15;if(path==="trade")score+=8;if(path==="military")score+=5;return clamp(score)}
function employmentScore(career){const outlook=(career.outlook?.category||"").toLowerCase();if(career.brightOutlook?.length||outlook.includes("bright"))return 90;if(outlook.includes("average")&&!outlook.includes("below"))return 68;if(outlook.includes("below"))return 42;return 55}
function calculate(){const p=PATHS[activePath],military=activePath==="military",trade=activePath==="trade",training=activePath==="training",median=Number(selectedCareer.wage?.annual_median||selectedCareer.wage?.annual_median_over||0)||null,civilianStarting=Number($("startingPay").value)||Math.round((median||55000)*.82);let starting=civilianStarting,gross=Number($("cost").value||0),aid=Number($("grants").value||0),duration=Number($("duration").value||0),earnWhile=Number($("earnWhile").value||0);const debt=Number($("debt").value||0);let tradeComp=null,trainingComp=null;if(trade){tradeComp=tradeInputs();gross=tradeComp.grossCost;aid=tradeComp.support;duration=0;starting=tradeComp.firstYearEarnings}if(training){trainingComp=trainingInputs();gross=trainingComp.grossCost;aid=trainingComp.support;duration=trainingComp.months;earnWhile=trainingComp.earnWhile;starting=trainingComp.success*trainingComp.salary+(1-trainingComp.success)*trainingComp.fallback}const netCost=Math.max(0,gross-aid),upfront=Math.max(0,netCost-debt),trainingYears=duration/12;let militaryComp=null,fiveYearEarnings,fiveYearNet;if(military){militaryComp=militaryInputs();starting=militaryComp.annualCash;const serviceYears=Math.min(5,militaryComp.commitment/12),civilianYears=Math.max(0,5-serviceYears);fiveYearEarnings=militaryComp.annualCash*serviceYears+militaryComp.bonus+civilianStarting*civilianYears;fiveYearNet=fiveYearEarnings+militaryComp.educationExpected-netCost-debt*.15}else if(trade){fiveYearEarnings=tradeComp.fiveYearEarnings;fiveYearNet=fiveYearEarnings-netCost-debt*.15}else if(training){fiveYearEarnings=trainingComp.fiveYearEarnings;fiveYearNet=trainingComp.fiveYearNet-debt*.15}else{fiveYearEarnings=earnWhile*trainingYears+starting*Math.max(0,5-trainingYears);fiveYearNet=fiveYearEarnings-netCost-debt*.15}const financial=clamp(42+(fiveYearNet-140000)/7000),time=clamp(100-duration*1.15),cost=clamp(100-(upfront/1200)-(debt/900)),demand=employmentScore(selectedCareer),ai=aiResilience(selectedCareer,activePath),related=selectedCareer.relatedOccupations?.length||0,industries=selectedCareer.industries?.length||0,flexibility=clamp(42+related*5+industries*3+(military?5:0));const metrics={"Financial outcome":financial,"Time to earnings":time,"Debt & upfront cost":cost,"Employment demand":demand,"AI resilience":ai,"Career flexibility":flexibility},score=clamp(financial*.28+time*.17+cost*.18+demand*.15+ai*.12+flexibility*.10),name=activePath==="college"?get(selectedSchool,"school.name"):(military?selectedMilitary.title:($("provider").value.trim()||p.label));const website=activePath==="college"?get(selectedSchool,"school.school_url"):null,degree=activePath==="college"?$("degree").options[$("degree").selectedIndex].text:null,residency=activePath==="college"?$("residency").value:null;return{id:crypto.randomUUID(),path:activePath,pathLabel:p.label,name,career:selectedCareer,inputs:{gross,aid,debt,netCost,upfront,duration,earnWhile,starting,civilianStarting},militaryComp,tradeComp,trainingComp,annualMedian:median,fiveYearNet,metrics,score,website,degree,residency}}
function category(score){return score>=80?["Strong fit","good"]:score>=65?["Promising","good"]:score>=50?["Mixed tradeoffs","mid"]:["Higher risk","low"]}
function recommendation(option){const sorted=Object.entries(option.metrics).sort((a,b)=>b[1]-a[1]),strengths=sorted.slice(0,2).map(x=>x[0].toLowerCase()).join(" and "),risk=sorted[sorted.length-1][0].toLowerCase();return`This path scores best on ${strengths}. Its biggest tradeoff is ${risk}. Compare that weakness with what matters most to you.`}
function monthlyDebt(debt){if(!debt)return 0;const rate=.065/12,payments=120;return debt*rate/(1-Math.pow(1+rate,-payments))}
function nextStep(option){if(option.path==="college"&&option.website){const url=/^https?:\/\//i.test(option.website)?option.website:`https://${option.website}`;return{label:"Visit this school’s website",url}}if(option.path==="military"){const branches={army:["Army","https://www.goarmy.com/"],air_force:["Air Force","https://www.airforce.com/"],navy:["Navy","https://www.navy.com/"],marine_corps:["Marine Corps","https://www.marines.com/"],coast_guard:["Coast Guard","https://www.gocoastguard.com/"],space_force:["Space Force","https://www.spaceforce.com/"]},match=branches[option.branch];return match?{label:`Visit the official ${match[0]} website`,url:match[1]}:{label:"Select and score this military path again",url:"#builder-title"}}if(option.path==="trade")return{label:"Find registered apprenticeships",url:"https://www.apprenticeship.gov/apprenticeship-job-finder"};return{label:"Verify training providers",url:"https://www.careeronestop.org/LocalHelp/EmploymentAndTraining/find-WIOA-training-programs.aspx"}}
function card(option,rank){const[label,tone]=category(option.score),m=option.militaryComp,t=option.tradeComp,c=option.trainingComp,link=nextStep(option);const metrics=Object.entries(option.metrics).map(([name,value])=>`<div class="metric"><div class="metric-label"><span>${escapeHtml(name)} <button class="info" type="button" data-tip="${escapeHtml(METRIC_HELP[name])}" aria-label="About ${escapeHtml(name)}">i</button></span><strong>${value}</strong></div><div class="bar"><i class="${value>=70?"high":value>=50?"medium":"low"}" style="width:${value}%"></i></div></div>`).join("");const pathFacts=m?`<div class="fact"><span>Pay grade</span><strong>${escapeHtml(m.grade)}</strong></div><div class="fact"><span>Annual cash compensation</span><strong>${money(m.annualCash)}</strong></div><div class="fact"><span>Service commitment</span><strong>${m.commitment} months</strong></div><div class="fact"><span>Expected education value</span><strong>${money(m.educationExpected)}</strong></div>`:t?`<div class="fact"><span>Starting apprentice wage</span><strong>${money(t.start)}/hr</strong></div><div class="fact"><span>Journey-level wage</span><strong>${money(t.journey)}/hr</strong></div><div class="fact"><span>Program length</span><strong>${t.months} months</strong></div><div class="fact"><span>First-year earnings</span><strong>${money(t.firstYearEarnings)}</strong></div>`:c?`<div class="fact"><span>Credential</span><strong>${escapeHtml(c.type)}</strong></div><div class="fact"><span>Completion × placement</span><strong>${Math.round(c.success*100)}%</strong></div><div class="fact"><span>Target salary</span><strong>${money(c.salary)}</strong></div><div class="fact"><span>Expected renewal cost</span><strong>${money(c.renewalExpected)}</strong></div>`:`<div class="fact"><span>Degree/program</span><strong>${escapeHtml(option.degree||"Selected program")}</strong></div><div class="fact"><span>Expected first-year pay</span><strong>${money(option.inputs.starting)}</strong></div><div class="fact"><span>Career median wage</span><strong>${money(option.annualMedian)}</strong></div>`;const timeLabel=t?"Paid from month 1":`${option.inputs.duration} months`,payment=monthlyDebt(option.inputs.debt);return`<article class="option-card ${rank===1?"best":""}"><div class="rank">${rank===1?"#1 · LEADING PATH":`#${rank} PATH`}</div><div class="option-body"><div class="path-tag ${option.path}">${escapeHtml(option.pathLabel)}</div><h3>${escapeHtml(option.name)}</h3><div class="career">${escapeHtml(option.career.name)} · ${escapeHtml(option.career.code)}</div><div class="score-row"><div class="big-score">${option.score}<small>/100</small></div><span class="pill ${tone}">${label}</span></div><div class="recommendation"><strong>Why this path received its score</strong><p>${escapeHtml(recommendation(option))}</p></div><div class="facts"><div class="fact"><span>5-year net value</span><strong>${money(option.fiveYearNet)}</strong></div><div class="fact"><span>Time to earnings</span><strong>${timeLabel}</strong></div><div class="fact"><span>Cash upfront</span><strong>${money(option.inputs.upfront??option.inputs.netCost)}</strong></div><div class="fact"><span>Expected debt</span><strong>${money(option.inputs.debt)}${payment?`<small class="debt-note">about ${money(payment)}/month</small>`:""}</strong></div>${pathFacts}</div><div class="metrics">${metrics}</div><a class="next-link" href="${escapeHtml(link.url)}" target="_blank" rel="noopener">${escapeHtml(link.label)} →</a><div class="source-note">Official/public source link. Verify costs, eligibility, pay, and deadlines directly.</div><button class="remove" data-remove="${option.id}">Remove path</button></div></article>`}
function renderPlan(ranked){$("planSection").hidden=!ranked.length;if(!ranked.length)return;const best=ranked[0],payment=monthlyDebt(best.inputs.debt),link=nextStep(best);$("planContent").innerHTML=`<div class="plan-grid"><div class="plan-stat"><span>Leading path</span><strong>${escapeHtml(best.name)}</strong></div><div class="plan-stat"><span>Estimated total cost</span><strong>${money(best.inputs.gross)}</strong></div><div class="plan-stat"><span>Expected debt</span><strong>${money(best.inputs.debt)}</strong>${payment?`<span>about ${money(payment)}/month</span>`:""}</div><div class="plan-stat"><span>Expected starting pay</span><strong>${money(best.inputs.starting)}</strong></div></div><div class="plan-steps"><h3>Your next steps</h3><ol><li>Verify the cost, timeline, eligibility, and outcome assumptions with the official source.</li><li>Ask for written details about aid, pay, placement, benefits, and total borrowing.</li><li>Compare the leading path with at least one lower-cost alternative before committing.</li><li><a href="${escapeHtml(link.url)}" target="_blank" rel="noopener">${escapeHtml(link.label)}</a>.</li></ol></div>`}
function render(){const ranked=[...comparisons].sort((a,b)=>b.score-a.score);$("emptyState").hidden=ranked.length>0;$("clearAll").hidden=ranked.length===0;$("comparisonGrid").innerHTML=ranked.map((o,i)=>card(o,i+1)).join("");$("featured").hidden=!ranked.length;if(ranked.length){const best=ranked[0];$("featured").innerHTML=`<div><div class="eyebrow">CURRENT LEADING PATH</div><div class="path-tag light">${escapeHtml(best.pathLabel)}</div><h2>${escapeHtml(best.name)}</h2><p>${escapeHtml(best.career.name)}</p><p>${escapeHtml(recommendation(best))}</p></div><div class="feature-score"><span>CAREERSHIELD SCORE</span><strong>${best.score}</strong><small>/100</small><p>${category(best.score)[0]} across all six factors</p></div>`}renderPlan(ranked);document.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{comparisons=comparisons.filter(o=>o.id!==b.dataset.remove);save();render()}))}

