$("schoolSearch").addEventListener("input",()=>{selectedSchool=null;$("schoolSelected").hidden=true;searchSchools()});$("careerSearch").addEventListener("input",()=>{selectedCareer=null;$("careerSelected").hidden=true;$("startingPay").value="";searchCareers()});$("militaryJobSearch").addEventListener("input",()=>{selectedMilitary=null;selectedCareer=null;$("militaryJobSelected").hidden=true;$("careerSelected").hidden=true;searchMilitaryJobs()});$("militaryBranch").addEventListener("change",()=>{$("militaryJobSearch").value="";$("militaryJobSelected").hidden=true;selectedMilitary=null;selectedCareer=null});$("militaryTrack").addEventListener("change",()=>{$("militaryJobSearch").value="";$("militaryJobSelected").hidden=true;selectedMilitary=null;selectedCareer=null;configurePayGrades()});$("payGrade").addEventListener("change",()=>{$("monthlyBasicPay").value=PAY_GRADES[$("militaryTrack").value][$("payGrade").value];updateMilitarySummary()});["monthlyBasicPay","monthlyHousing","monthlyFood","monthlySpecialPay","militaryBonus","serviceCommitment","educationBenefit","benefitRealization"].forEach(id=>$(id).addEventListener("input",updateMilitarySummary));["tradeStartWage","tradeJourneyWage","tradeProgramMonths","tradeRaises","tradeHoursWeek","tradeWeeksYear","tradeToolsCost","tradeClassCost","tradeLicenseCost","tradeSupport"].forEach(id=>$(id).addEventListener("input",updateTradeSummary));["credentialType","trainingMonths","trainingTuition","trainingExamCost","trainingMaterials","trainingRenewal","trainingSupport","trainingEarnWhile","completionProbability","placementRate","trainingStartingSalary","fallbackSalary"].forEach(id=>$(id).addEventListener("input",updateTrainingSummary));["degree","residency"].forEach(id=>$(id).addEventListener("change",schoolTuition));$("debt").addEventListener("input",updateDebtGuidance);$("printPlan").addEventListener("click",()=>window.print());document.addEventListener("click",e=>{if(!e.target.closest(".searchbox")){$("schoolResults").hidden=true;$("careerResults").hidden=true;$("militaryJobResults").hidden=true}});
$("addOption").addEventListener("click",()=>{$("formMessage").textContent="";if(activePath==="college"&&!selectedSchool)return $("formMessage").textContent="Select a school from the live College Scorecard results.";if(activePath==="military"&&!selectedMilitary)return $("formMessage").textContent="Select a military specialty from the official search results.";if(!selectedCareer)return $("formMessage").textContent=activePath==="military"?"Choose a civilian career match for the military specialty.":"Select a career from the live O*NET results.";if(comparisons.length>=4)return $("formMessage").textContent="Your comparison already has four paths. Remove one to add another.";comparisons.push(calculate());save();render();$("featured").scrollIntoView({behavior:"smooth",block:"start"})});$("clearAll").addEventListener("click",()=>{comparisons=[];save();render()});
