renderMilitaryChoice=async job=>{selectedMilitary=job;$("militaryJobSearch").value=`${job.code} · ${job.title}`;const match=(job.occupations||[])[0];$("militaryJobSelected").innerHTML=`<strong>${escapeHtml(job.title)}</strong><small>CareerShield scores this specialty directly. Related civilian occupations are used only as background labor-market signals.</small>`;$("militaryJobSelected").hidden=false;selectedCareer=null;if(match){try{selectedCareer=await api(`/api/careers?code=${encodeURIComponent(match.code)}`)}catch{selectedCareer={code:match.code,name:job.title,description:job.title,relatedOccupations:job.occupations||[],industries:[],tasks:[],outlook:null,wage:null}}}else selectedCareer={code:job.code,name:job.title,description:job.title,relatedOccupations:[],industries:[],tasks:[],outlook:null,wage:null}};
militaryInputs=()=>{const monthlyBasic=Number($("monthlyBasicPay").value||0),housing=Number($("monthlyHousing").value||0),food=Number($("monthlyFood").value||0),special=Number($("monthlySpecialPay").value||0),bonus=Number($("militaryBonus").value||0),commitment=Number($("serviceCommitment").value||0),education=Number($("educationBenefit").value||0);return{grade:$("payGrade").value,dutyZip:$("dutyZip").value,dependentStatus:$("dependentStatus").value,monthlyBasic,housing,food,special,bonus,commitment,education,educationExpected:education,annualCash:(monthlyBasic+housing+food+special)*12}};

const calculateV411Base=calculate,setPathV411Base=setPath;
const selectedDegreePlan=()=>$("collegePlan").value.trim();
document.querySelectorAll(".path-choice").forEach(button=>button.addEventListener("click",()=>{$("collegePlanField").hidden=button.dataset.path!=="college"}));
calculate=()=>{const option=calculateV411Base();if(option.path==="college"){option.degreePlan=selectedDegreePlan();option.degree=$("collegePlan").options[$("collegePlan").selectedIndex]?.text||"Selected degree plan"}if(option.path==="military"){option.branch=$("militaryBranch").value;option.career={...option.career,name:selectedMilitary?.title||option.career?.name};option.inputs={...option.inputs,gross:0,aid:0,debt:0,netCost:0,upfront:0,duration:0};option.metrics["Time to earnings"]=100;option.metrics["Debt & upfront cost"]=100;option.score=clamp(option.metrics["Financial outcome"]*.28+100*.17+100*.18+option.metrics["Employment demand"]*.15+option.metrics["AI resilience"]*.12+option.metrics["Career flexibility"]*.10)}return option};
setPath=(path,initial=false)=>{setPathV411Base(path,initial);const military=path==="military";$("providerField").hidden=true;$("careerField").hidden=military;if(military){$("costField").hidden=true;$("aidField").hidden=true;$("durationField").hidden=true;$("earnWhileField").hidden=true;$("startingPayField").hidden=true;$("cost").value="0";$("grants").value="0";$("debt").value="0";$("duration").value="0"}if(path==="college"){$("careerLabel").textContent="Degree plan";$("careerSearch").placeholder="Type a field such as nursing or accounting"}if(path==="trade"||path==="training"){$("careerLabel").textContent="Target career";$("careerSearch").placeholder="Type a career to choose"}};

