setPath=(path,initial=false)=>{setPathDropdownBase(path,initial);if(path==="trade"||path==="training")loadTrainingCareers();if(path==="college")loadCollegeCareers()};

let selectedBah=null;
const loadBah=debounce(async()=>{const zip=$("dutyZip").value.trim(),grade=$("payGrade").value,dependents=$("dependentStatus").value;selectedBah=null;if(zip.length!==5){$("monthlyHousing").value="0";$("bahStatus").textContent="Enter a five-digit duty ZIP to load the official 2026 DoD rate.";updateMilitarySummary();return}$("bahStatus").textContent="Loading the official 2026 DoD BAH rate…";try{selectedBah=await api(`/api/bah?zip=${encodeURIComponent(zip)}&grade=${encodeURIComponent(grade)}&dependents=${encodeURIComponent(dependents)}`);$("monthlyHousing").value=selectedBah.monthly;$("bahStatus").textContent=`Official 2026 rate for ${selectedBah.location} · ${grade} · ${dependents} dependents.`}catch(error){$("monthlyHousing").value="0";$("bahStatus").textContent=error.message}updateMilitarySummary()},250);
