function applySelectedProgram(){const option=$("collegePlan").selectedOptions[0],index=Number(option?.dataset.programIndex);selectedProgram=option?.value!==""&&Number.isInteger(index)?schoolProgramChoices[index]:null;if(!selectedProgram)return;const credential=selectedProgram.credential.toLowerCase();const months=credential.includes("associate")?24:credential.includes("bachelor")?48:credential.includes("certificate")?12:credential.includes("master")||credential.includes("doctoral")||credential.includes("professional")?72:Number($("degree").value||48);const degreeOption=[...$("degree").options].find(item=>Number(item.value)===months);if(degreeOption)$("degree").value=degreeOption.value;schoolTuition();if(selectedProgram.debt)$("debt").value=Math.round(selectedProgram.debt);if(selectedProgram.earnings)$("startingPay").value=Math.round(selectedProgram.earnings);updateDebtGuidance();const facts=[selectedProgram.earnings?`reported earnings ${money(selectedProgram.earnings)}`:"earnings suppressed or unavailable",selectedProgram.debt?`reported median debt ${money(selectedProgram.debt)}`:"program debt suppressed or unavailable"];$("collegePlanHint").textContent=`College Scorecard: ${facts.join(" · ")}. Tuition is estimated from the school rate and credential length because federal data does not publish tuition by major.`}
$("collegePlan").addEventListener("change",applySelectedProgram);
$("schoolSearch").addEventListener("input",()=>{selectedProgram=null;schoolProgramChoices=[]});

const floatingInfoTooltip=document.createElement("div");
floatingInfoTooltip.className="floating-info-tooltip";
floatingInfoTooltip.setAttribute("role","tooltip");
floatingInfoTooltip.hidden=true;
document.body.appendChild(floatingInfoTooltip);
function showFloatingInfo(button){const text=button.dataset.tip;if(!text)return;floatingInfoTooltip.textContent=text;floatingInfoTooltip.hidden=false;const buttonRect=button.getBoundingClientRect(),tipRect=floatingInfoTooltip.getBoundingClientRect(),margin=8;let left=buttonRect.left+buttonRect.width/2-tipRect.width/2;left=Math.max(margin,Math.min(left,window.innerWidth-tipRect.width-margin));let top=buttonRect.top-tipRect.height-9;if(top<margin)top=Math.min(window.innerHeight-tipRect.height-margin,buttonRect.bottom+9);floatingInfoTooltip.style.left=`${Math.round(left)}px`;floatingInfoTooltip.style.top=`${Math.round(top)}px`}
function hideFloatingInfo(){floatingInfoTooltip.hidden=true}
document.addEventListener("pointerover",event=>{const button=event.target.closest?.(".info");if(button&&!button.contains(event.relatedTarget))showFloatingInfo(button)});
document.addEventListener("pointerout",event=>{const button=event.target.closest?.(".info");if(button&&!button.contains(event.relatedTarget))hideFloatingInfo()});
document.addEventListener("focusin",event=>{const button=event.target.closest?.(".info");if(button)showFloatingInfo(button)});
document.addEventListener("focusout",event=>{if(event.target.closest?.(".info"))hideFloatingInfo()});
window.addEventListener("scroll",hideFloatingInfo,true);
window.addEventListener("resize",hideFloatingInfo);

function updateSavedProgress(){const panel=$("savedProgress");panel.hidden=!comparisons.length;if(!comparisons.length)return;const recent=comparisons.slice(-3).reverse().map(option=>option.name).filter(Boolean);$("savedProgressText").textContent=`${comparisons.length} saved path${comparisons.length===1?"":"s"}${recent.length?` · Recent: ${recent.join(" · ")}`:""}`}
const saveWithProgress=save;
save=(sync=true)=>{saveWithProgress(sync);updateSavedProgress()};
$("viewSavedPaths").addEventListener("click",()=>document.querySelector(".comparison").scrollIntoView({behavior:"smooth",block:"start"}));
$("restartApp").addEventListener("click",async()=>{if(!window.confirm("Restart CareerShield and permanently clear all saved paths and current selections?"))return;comparisons=[];save();localStorage.removeItem(ASSISTANT_USAGE_KEY);if(window.CareerShieldAccount?.syncPlans)await window.CareerShieldAccount.syncPlans([]).catch(()=>{});window.location.hash="builder-title";window.location.reload()});
updateSavedProgress();
window.CareerShieldPlans={get:()=>comparisons.map(plan=>({...plan})),replace:plans=>{comparisons=Array.isArray(plans)?plans.slice(0,4):[];save(false);render();updateSavedProgress()},set:plans=>{comparisons=Array.isArray(plans)?plans.slice(0,4):[];save(true);render();updateSavedProgress()}};

// V4.3 guided builder and richer results
let builderStage=1;
const builderStageTwo=["trainingModeField","schoolField","degreeField","residencyField","collegePlanField","providerField","militaryBranchField","militaryTrackField","militaryJobField","careerField"];
const builderStageThree=["militaryCompensation","tradeEconomics","trainingEconomics","costField","aidField","debtField","durationField","earnWhileField","startingPayField"];
function applyBuilderStage(stage){builderStage=Math.max(1,Math.min(3,stage));$("pathPicker").classList.toggle("stage-hidden",builderStage!==1);builderStageTwo.forEach(id=>$(id)?.classList.toggle("stage-hidden",builderStage!==2));builderStageThree.forEach(id=>$(id)?.classList.toggle("stage-hidden",builderStage!==3));document.querySelectorAll("[data-progress]").forEach(item=>item.classList.toggle("active",Number(item.dataset.progress)<=builderStage));$("builderBack").hidden=builderStage===1;$("builderNext").hidden=builderStage===3;$("addOption").hidden=builderStage!==3;$("formMessage").textContent=""}
$("builderNext").addEventListener("click",()=>applyBuilderStage(builderStage+1));
$("builderBack").addEventListener("click",()=>applyBuilderStage(builderStage-1));
document.querySelectorAll("[data-home-path]").forEach(button=>button.addEventListener("click",()=>{const path=button.dataset.homePath;setPath(path);showCombinedTraining(path);applyBuilderStage(2);$("builder-title").scrollIntoView({behavior:"smooth",block:"start"})}));
$("addOption").addEventListener("click",()=>setTimeout(()=>{if(!$("formMessage").textContent)applyBuilderStage(1)},0));

const calculateV43Base=calculate;
calculate=()=>{const option=calculateV43Base();const t=option.tradeComp,c=option.trainingComp,m=option.militaryComp;let nextAnnual=Number(option.inputs.starting||option.annualMedian||0);if(t)nextAnnual=Number(t.journey||0)*Number(t.hoursWeek||40)*Number(t.weeksYear||50);if(c)nextAnnual=Number(c.success||0)*Number(c.salary||0)+(1-Number(c.success||0))*Number(c.fallback||0);if(m)nextAnnual=Number(option.inputs.civilianStarting||m.annualCash||0);option.tenYearNet=Math.round(Number(option.fiveYearNet||0)+nextAnnual*5.4);return option};
function tenYearValue(option){if(Number.isFinite(Number(option.tenYearNet)))return Number(option.tenYearNet);const annual=Number(option.inputs?.starting||option.annualMedian||0);return Math.round(Number(option.fiveYearNet||0)+annual*5.4)}
function updatePathPrompt(){const count=comparisons.length,title=$("pathPromptTitle"),copy=$("pathPromptText"),button=$("startAnotherPath");$("emptyState").hidden=false;if(!count){title.textContent="No paths scored yet.";copy.textContent="Add up to four routes. Mix college, trades, certifications, and military options in one comparison.";button.hidden=true}else if(count<4){title.textContent="Want to compare another option?";copy.textContent=`You have ${count} scored path${count===1?"":"s"}. Add another route to make the side-by-side comparison more useful.`;button.textContent="Start another path";button.hidden=false}else{title.textContent="Your four-path comparison is ready.";copy.textContent="Remove a path below if you want to compare a different option.";button.hidden=true}}
function renderResultsVisual(){const target=$("resultsVisual"),ranked=[...comparisons].sort((a,b)=>b.score-a.score);updatePathPrompt();target.hidden=!ranked.length;if(!ranked.length)return;const maximum=Math.max(1,...ranked.map(option=>Math.max(0,tenYearValue(option))));target.innerHTML=`<h3>10-year comparison outlook</h3><p>Directional projection using the same path assumptions and a modest earnings-growth allowance. Verify all figures before deciding.</p>${ranked.map(option=>{const value=tenYearValue(option),width=Math.max(3,Math.round(Math.max(0,value)/maximum*100));return`<div class="visual-row"><strong>${escapeHtml(option.savedLabel||option.name)}</strong><div class="visual-bar" aria-label="10-year projected net value ${money(value)}"><i style="width:${width}%"></i></div><div class="visual-stat"><span>Score</span><b>${option.score}/100</b></div><div class="visual-stat"><span>10-year net</span><b>${money(value)}</b></div><div class="visual-stat"><span>Debt</span><b>${money(option.inputs?.debt||0)}</b></div></div>`}).join("")}`}
const renderV43Base=render;
render=()=>{renderV43Base();renderResultsVisual()};
applyBuilderStage(1);
renderResultsVisual();

// Post-9/11 GI Bill earned-benefit estimator (VA rates effective August 1, 2026)
const GI_BILL_PRIVATE_ANNUAL_CAP=30908.34,GI_BILL_BOOKS_ANNUAL_CAP=1000,GI_BILL_ONLINE_MHA_CAP=1261;
function giBillEligibility(months){if(months>=36)return 1;if(months>=30)return .9;if(months>=24)return .8;if(months>=18)return .7;if(months>=6)return .6;if(months>=3)return .5;return 0}
function updateGiBillEstimate(){const months=Number($("serviceCommitment").value||0),tier=giBillEligibility(months),type=$("giBillSchoolType").value,years=Number($("giBillAcademicYears").value||0),enteredTuition=Number($("giBillAnnualTuition").value||0);let annualTuition=enteredTuition;if(type==="private"||type==="technical")annualTuition=Math.min(enteredTuition,GI_BILL_PRIVATE_ANNUAL_CAP);const monthlyHousing=type==="online"?GI_BILL_ONLINE_MHA_CAP:Number($("giBillMonthlyHousing").value||0),tuition=annualTuition*years*tier,housing=monthlyHousing*9*years*tier,books=GI_BILL_BOOKS_ANNUAL_CAP*years*tier,total=Math.round(tuition+housing+books);$("educationBenefit").value=total;$("giBillEstimateNote").textContent=tier?`${Math.round(tier*100)}% estimated eligibility · ${money(tuition)} tuition + ${money(housing)} housing + ${money(books)} books. Future earned benefit; not immediate military pay.`:"No benefit included yet. At least 90 days of qualifying active-duty service is generally required.";updateMilitarySummary()}
const loadGiBillHousing=debounce(async()=>{const zip=$("giBillSchoolZip").value.trim(),type=$("giBillSchoolType").value;if(type==="online"){$("giBillMonthlyHousing").value=GI_BILL_ONLINE_MHA_CAP;$("giBillHousingStatus").textContent=`Online-only estimate uses the current VA maximum of ${money(GI_BILL_ONLINE_MHA_CAP)} per month.`;updateGiBillEstimate();return}if(zip.length!==5){$("giBillMonthlyHousing").value="0";$("giBillHousingStatus").textContent="Enter the five-digit ZIP where most in-person classes will be taken.";updateGiBillEstimate();return}$("giBillHousingStatus").textContent="Loading the official E-5-with-dependents housing rate…";try{const result=await api(`/api/bah?zip=${encodeURIComponent(zip)}&grade=E-5&dependents=with`);$("giBillMonthlyHousing").value=result.monthly;$("giBillHousingStatus").textContent=`Official 2026 housing basis for ${result.location}. Actual VA payment also depends on enrollment.`}catch(error){$("giBillMonthlyHousing").value="0";$("giBillHousingStatus").textContent=error.message}updateGiBillEstimate()},250);
[$("serviceCommitment"),$("giBillAnnualTuition"),$("giBillAcademicYears")].forEach(control=>control.addEventListener("input",updateGiBillEstimate));
$("giBillSchoolType").addEventListener("change",loadGiBillHousing);
$("giBillSchoolZip").addEventListener("input",loadGiBillHousing);
updateGiBillEstimate();

// Keep the college debt estimate aligned with tuition remaining after grants.
function syncCollegeDebtToCost(){if(activePath!=="college")return;const remaining=Math.max(0,Math.round(Number($("cost").value||0)-Number($("grants").value||0)));$("debt").value=remaining;updateDebtGuidance();$("debtGuidance").textContent=`Estimated debt equals tuition remaining after grants: ${money(remaining)}. Add scholarships or grants above to reduce it.`}
const schoolTuitionBeforeDebtSync=schoolTuition;
schoolTuition=()=>{schoolTuitionBeforeDebtSync();syncCollegeDebtToCost()};
[$("cost"),$("grants")].forEach(control=>control.addEventListener("input",syncCollegeDebtToCost));
[$("degree"),$("residency"),$("collegePlan")].forEach(control=>control.addEventListener("change",()=>setTimeout(syncCollegeDebtToCost,0)));
$("schoolResults").addEventListener("click",event=>{if(event.target.closest("button.result"))setTimeout(syncCollegeDebtToCost,0)});
document.querySelectorAll(".path-choice").forEach(button=>button.addEventListener("click",()=>{$("debt").readOnly=button.dataset.path==="college";if(button.dataset.path==="college")setTimeout(syncCollegeDebtToCost,0)}));
$("debt").readOnly=activePath==="college";

// V4.3 dedicated on-screen and printable plan.
renderPlan=ranked=>{const section=$("planSection");section.hidden=!ranked.length;if(!ranked.length)return;const best=ranked[0],payment=monthlyDebt(best.inputs?.debt||0),link=nextStep(best),generated=new Date().toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}),metricRows=Object.entries(best.metrics||{}).map(([name,score])=>`<div class="print-factor"><span>${escapeHtml(name)}</span><strong>${score}/100</strong></div>`).join(""),comparisonRows=ranked.map((option,index)=>`<tr><td>${index+1}</td><td><strong>${escapeHtml(option.savedLabel||option.name)}</strong><small>${escapeHtml(option.pathLabel||option.path)}</small></td><td>${option.score}/100</td><td>${money(option.inputs?.gross||0)}</td><td>${money(option.inputs?.debt||0)}</td><td>${money(option.inputs?.starting||option.annualMedian||0)}</td><td>${money(tenYearValue(option))}</td></tr>`).join("");section.innerHTML=`<div class="print-plan-brand"><div><span>CAREERSHIELD</span><h1>My Career Decision Plan</h1><p>Prepared ${escapeHtml(generated)}</p></div><div class="print-score"><strong>${best.score}</strong><span>/100</span></div></div><section class="print-plan-lead"><span>RECOMMENDED LEADING PATH</span><h2>${escapeHtml(best.savedLabel||best.name)}</h2><p>${escapeHtml(best.career?.name||best.pathLabel||"")}</p><strong>${escapeHtml(recommendation(best))}</strong></section><div class="plan-grid print-plan-stats"><div class="plan-stat"><span>Estimated total cost</span><strong>${money(best.inputs?.gross||0)}</strong></div><div class="plan-stat"><span>Estimated debt</span><strong>${money(best.inputs?.debt||0)}</strong>${payment?`<span>About ${money(payment)}/month for 10 years at 6.5%</span>`:""}</div><div class="plan-stat"><span>Expected starting earnings</span><strong>${money(best.inputs?.starting||best.annualMedian||0)}</strong></div><div class="plan-stat"><span>10-year projected net</span><strong>${money(tenYearValue(best))}</strong></div></div>${best.militaryComp?.education?`<div class="print-benefit"><span>Earned future education benefit</span><strong>${money(best.militaryComp.education)} estimated Post-9/11 GI Bill value</strong><small>Shown separately from immediate military pay and subject to VA eligibility.</small></div>`:""}<section class="print-plan-section"><h3>Why this path leads</h3><div class="print-factors">${metricRows}</div></section><section class="print-plan-section"><h3>Side-by-side summary</h3><div class="print-table-wrap"><table class="print-comparison"><thead><tr><th>Rank</th><th>Path</th><th>Score</th><th>Cost</th><th>Debt</th><th>Starting earnings</th><th>10-year net</th></tr></thead><tbody>${comparisonRows}</tbody></table></div></section><section class="print-plan-section print-actions"><h3>My next steps</h3><ol><li>Confirm tuition, aid, pay, program length, eligibility, and outcomes with the official organization.</li><li>Request written details about every cost, scholarship, benefit, placement claim, and required commitment.</li><li>Compare this path with the strongest lower-cost alternative before signing or borrowing.</li><li>Visit: <a href="${escapeHtml(link.url)}" target="_blank" rel="noopener">${escapeHtml(link.label)}</a><small>${escapeHtml(link.url)}</small></li></ol></section><section class="print-plan-notes"><h3>Important assumptions</h3><p>CareerShield estimates are directional decision support, not a guarantee or financial advice. Earnings, debt, housing, benefits, employment demand, and AI resilience can change. Verify all figures with the school, employer, training provider, recruiter, VA, or relevant government agency.</p><p><strong>Primary data sources:</strong> U.S. Department of Education College Scorecard, U.S. Department of Labor O*NET, U.S. Department of Defense pay and BAH data, and U.S. Department of Veterans Affairs education-benefit rates.</p></section><button id="printPlan" class="secondary" type="button">Print or save this plan</button>`;$("printPlan").addEventListener("click",()=>window.print())};
render();

// Allow direct navigation between all guided-builder stages.
const applyBuilderStageBeforeClickableProgress=applyBuilderStage;
applyBuilderStage=stage=>{applyBuilderStageBeforeClickableProgress(stage);document.querySelectorAll(".builder-progress [data-progress]").forEach(button=>{const current=Number(button.dataset.progress)===builderStage;button.toggleAttribute("aria-current",current)})};
document.querySelectorAll(".builder-progress [data-progress]").forEach(button=>button.addEventListener("click",()=>applyBuilderStage(Number(button.dataset.progress))));
applyBuilderStage(builderStage);
$("startAnotherPath").addEventListener("click",()=>{applyBuilderStage(1);$("builder-title").scrollIntoView({behavior:"smooth",block:"start"})});
